use xiom.io;

enum ConfigValue {
  Number(n: Int),
  Text(s: Str),
  YesNo(b: Bool),
}

fn ConfigValue.display(self) -> Str {
  match self {
    Number(n) => { return "number: " + n; }
    Text(s) => { return "text: " + s; }
    YesNo(b) => {
      if b { return "yes"; }
      return "no";
    }
  }
}

fn ConfigValue.as_number(self) -> Int {
  match self {
    Number(n) => { return n; }
    Text(_) => { return 0; }
    YesNo(b) => {
      if b { return 1; }
      return 0;
    }
  }
}

fn main() -> Int {
  let v1 = ConfigValue.Number(42);
  let v2 = ConfigValue.Text("hello");
  let v3 = ConfigValue.YesNo(true);
  return v1.as_number() + v2.as_number() + v3.as_number();
}
